//! 🧯️ A fault-only receiver retains bytes from the authenticated ActorFailure protocol.
use semio_framework_job::{OriginalNativeRecipientIdentity,OriginalNativeRetirement,OriginalTurnFailure,StepContext};
use semio_framework_value::{RetainedCloneProgress,ValueError,ValueRefusalKind};
use std::mem::{ManuallyDrop,size_of};
use crate::original_unit_flow::ActorFailurePermit;
pub(crate) struct ActorFailureHome{bytes:ManuallyDrop<Vec<u8>>,recipient:Option<OriginalNativeRecipientIdentity>,expected:Option<usize>,sealed:bool}
impl ActorFailureHome{
 pub(crate) fn empty()->Self{Self{bytes:ManuallyDrop::new(Vec::new()),recipient:None,expected:None,sealed:false}}
 fn verify(&self,permit:&ActorFailurePermit,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if self.recipient.is_none_or(|recipient|!permit.proves(recipient,cx)){return Err(refused().into())}Ok(())}
 pub(crate) fn bind_step(&mut self,recipient:OriginalNativeRecipientIdentity,permit:&ActorFailurePermit,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !permit.proves(recipient,cx){return Err(refused().into())}if let Some(existing)=self.recipient{return if existing==recipient{Ok(true)}else{Err(refused().into())}}if !pay(cx,size_of::<Option<OriginalNativeRecipientIdentity>>(),0)?{return Ok(false)}self.recipient=Some(recipient);Ok(true)}
 pub(crate) fn prepare(&mut self,permit:&ActorFailurePermit,length:usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.verify(permit,cx)?;if length>semio_framework_job_payload::JOB_PAYLOAD_OPERATION_BYTES{return Err(refused().into())}if let Some(expected)=self.expected{return if expected==length{Ok(true)}else{Err(refused().into())}}let grant=cx.retained_grant();if cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_depth==0||grant.maximum_capacity_bytes<length||grant.maximum_copy_bytes<size_of::<Option<usize>>(){return Ok(false)}self.bytes.try_reserve_exact(length).map_err(|_|refused())?;self.expected=Some(length);cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<Option<usize>>(),retained_capacity_bytes:self.bytes.capacity(),..Default::default()})?;cx.consume_fuel(1);Ok(true)}
 pub(crate) fn append_page(&mut self,permit:&ActorFailurePermit,offset:usize,page:&[u8],cursor:&mut usize,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.verify(permit,cx)?;let expected=self.expected.ok_or_else(refused)?;if self.sealed||*cursor>page.len()||offset.checked_add(*cursor)!=Some(self.bytes.len())||offset.checked_add(page.len()).is_none_or(|end|end>expected){return Err(refused().into())}if *cursor==page.len(){return Ok(true)}let grant=cx.retained_grant();let metadata=2*size_of::<usize>();let count=(page.len()-*cursor).min(grant.maximum_copy_bytes.saturating_sub(metadata)).min(usize::try_from(cx.fuel_remaining().saturating_sub(1)).unwrap_or(usize::MAX));if cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_depth==0||count==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:count+metadata,..Default::default()})?;cx.consume_fuel(u64::try_from(count).unwrap_or(u64::MAX)+1);self.bytes.extend_from_slice(&page[*cursor..*cursor+count]);*cursor+=count;Ok(*cursor==page.len())}
 pub(crate) fn seal(&mut self,permit:&ActorFailurePermit,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.verify(permit,cx)?;if self.sealed{return Ok(true)}if self.expected!=Some(self.bytes.len()){return Err(refused().into())}if !pay(cx,size_of::<bool>(),0)?{return Ok(false)}self.sealed=true;Ok(true)}
 pub(crate) fn bytes(&self)->Result<&[u8],ValueError>{if !self.sealed{return Err(refused())}Ok(&self.bytes)}
 pub(crate) fn sealed(&self)->bool{self.sealed}
}
impl OriginalNativeRetirement for ActorFailureHome{
 fn close_on_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let grant=cx.retained_grant();if cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_depth==0{return Ok(false)}if !self.bytes.is_empty(){let metadata=size_of::<usize>();if grant.maximum_copy_bytes<=metadata{return Ok(false)}let count=self.bytes.len().min(grant.maximum_copy_bytes-metadata);cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:count+metadata,..Default::default()})?;cx.consume_fuel(1);let keep=self.bytes.len()-count;self.bytes.truncate(keep);return Ok(false)}if self.bytes.capacity()!=0{let capacity=self.bytes.capacity();if !pay(cx,size_of::<Vec<u8>>(),capacity)?{return Ok(false)}drop(std::mem::take(&mut*self.bytes));return Ok(false)}if self.recipient.is_some()||self.expected.is_some()||self.sealed{if !pay(cx,size_of::<Self>(),0)?{return Ok(false)}self.recipient=None;self.expected=None;self.sealed=false;}Ok(true)}
 fn terminal_is_empty(&self)->bool{self.bytes.is_empty()&&self.bytes.capacity()==0&&self.recipient.is_none()&&self.expected.is_none()&&!self.sealed}
}
impl Drop for ActorFailureHome{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"actor failure receiver requires Source-funded retirement");if self.bytes.is_empty()&&self.bytes.capacity()==0{unsafe{ManuallyDrop::drop(&mut self.bytes)}}}}

/// 📬️ Only the verified ActorFailure recipient can become this fault capsule.
pub struct ActorFailureCapsule{native:Option<semio_framework_job::OriginalNativeLease<ActorFailureHome>>}
impl ActorFailureCapsule{
 pub(crate) fn take_step(native:&mut Option<semio_framework_job::OriginalNativeLease<ActorFailureHome>>,permit:&ActorFailurePermit,cx:&mut StepContext<'_>)->Result<Option<Self>,OriginalTurnFailure>{let lease=native.as_mut().ok_or_else(refused)?;let recipient=lease.recipient_identity();if !permit.proves(recipient,cx){return Err(refused().into())}let mut sealed=false;if !lease.with_native(cx,|home,cx|{home.verify(permit,cx)?;sealed=home.sealed();Ok(())})?||!sealed||!pay(cx,size_of::<Self>(),0)?{return Ok(None)}Ok(Some(Self{native:native.take()}))}
 pub(crate) fn with_bytes(&mut self,cx:&mut StepContext<'_>,receive:impl FnOnce(&[u8],&mut StepContext<'_>)->Result<(),OriginalTurnFailure>)->Result<bool,OriginalTurnFailure>{self.native.as_mut().ok_or_else(refused)?.with_native(cx,|home,cx|receive(home.bytes()?,cx))}
 pub(crate) fn return_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let Some(native)=self.native.as_mut()else{return Ok(true)};if !native.return_step(cx)?||!pay(cx,size_of::<Option<semio_framework_job::OriginalNativeLease<ActorFailureHome>>>(),0)?{return Ok(false)}self.native.take();Ok(true)}
 pub(crate) fn terminal_is_empty(&self)->bool{self.native.is_none()}
}
fn pay(cx:&mut StepContext<'_>,bytes:usize,release:usize)->Result<bool,OriginalTurnFailure>{let grant=cx.retained_grant();if cx.retirement_should_yield()||grant.maximum_items==0||grant.maximum_copy_bytes<bytes||grant.maximum_release_bytes<release||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,released_bytes:release,..Default::default()})?;cx.consume_fuel(1);Ok(true)}
fn refused()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"ActorFailure receiver requires its exact Source and verified recipient")}
